from (values
  ('GF-26-0896', 'https://google.com/maps/place/33°30''34.1"N+7°39''44.5"W/@33.5117334,-7.6637229,1671m/data=!3m1!1e3!4m12!1m7!3m6!1s0xda62d1505122c4b:0x8a0c1e6cd5a6c538!2sSuccursale+Renault+Sidi+Maarouf!8m2!3d33.5117334!4d-7.6611426!16s%2Fg%2F11h3mp6sv9!3m3!8m2!3d33.509461!4d-7.66236?entry=ttu&g_ep=EgoyMDI2MDYyNC4wIKXMDSoASAFQAw%3D%3D'),
