notify pgrst, 'reload schema';

select (select count(*) from public.terrains) as terrains,
       (select count(*) from public.terrains where coalesce(mymaps, '') <> '') as terrains_avec_infos_mymaps,
       (select count(distinct terrain_id) from public.carte_contours()) as terrains_avec_contour,
       (select count(*) from public.terrain_contours where cle like 'GF-%') as contours_par_reference;
